// One of the two packages. Its `pick<T>` answers its *second* argument, where
// the root package's answers its first, so a call that reached the wrong
// instantiation changes the program's exit code rather than quietly agreeing
// with it.
//
// The template is declared and instantiated here rather than exported: WP18
// §11 G7 refuses instantiating a generic from another module for now, which is
// also why the instantiating module's package prefix is the declaring module's.

const pick = <T>(a: T, b: T): T => b;

export const chooseA = (): i32 => pick(3, 7);
